import {activeFrame} from '../systems/profile.js';
import {scene} from './scene.js';
import {nextGoal,nextUnlock} from '../systems/goals.js';
import {starterEligible} from '../systems/monetization.js';
import {CONFIG,JOBS,ITEMS,SKILLS,HOUSING,ACHIEVEMENTS,DAILY_QUESTS,xpNeeded} from '../data/config.js';
import {income,jobRequirements,trainingCost,trainingDuration,statValue} from '../core/game.js';
import {t,money,number,compact} from '../locales/index.js';import {icon} from './icons.js';
const action=(name,id='')=>`data-action="${name}" data-id="${id}"`;
export function button(label,name,id='',cls='button',disabled=false,extra=''){return `<button class="${cls}" ${action(name,id)} ${disabled?'disabled':''} ${extra}>${label}</button>`;}
export const progress=(n,max,cls='')=>`<div class="progress ${cls}" role="progressbar" aria-valuenow="${Math.min(max,n)}" aria-valuemin="0" aria-valuemax="${max}" aria-label="${t('ui.goal')}"><span style="width:${Math.min(100,Math.max(0,n/max*100))}%"></span></div>`;
export const goal=nextGoal;
export function goalText(g){return g.key?t('ui.'+g.key):g.kind==='skill'?`${t('skill.'+g.id)} → ${g.value}`:g.kind==='career'?`${t('ui.unlock')}: ${t('job.'+g.id)}`:g.kind==='job'?`${t('ui.unlock')}: ${t('job.'+g.id)}`:`${t('ui.buy')}: ${t('item.'+g.id)}`;}
export function unlockText(s){const n=nextUnlock(s);if(n.kind==='done')return t('ui.max');return `${n.kind==='job'?t('job.'+n.id):n.kind==='housing'?t('home.'+n.id):t('ui.'+n.kind)} · ${t('ui.level')} ${n.level}`;}
export function header(s){return `<header class="topbar"><div class="brand"><span class="brandmark">z<span>·</span></span><div><strong>${t('ui.title')}</strong><small>IDLE LIFE</small></div></div>${button(icon('settings'),'settings','','icon-button',false,`aria-label="${t('ui.settings')}"`)}</header><div class="wallet"><button class="player-badge" data-action="profile" aria-label="${t('ui.profile')}"><span class="avatar profile-avatar frame-${activeFrame(s)}"><span>Z</span></span><div><strong>${t('ui.level')} <span id="level-value">${s.level}</span></strong><div class="xp-track"><span id="xp-fill" style="width:${s.level===CONFIG.maxLevel?100:s.xp/xpNeeded(s.level)*100}%"></span></div><small id="xp-label">${s.level===CONFIG.maxLevel?t('ui.max'):`${number(s.xp)} / ${number(xpNeeded(s.level))} XP`}</small></div></button><div class="balances"><div class="money-value">${icon('coin')}<strong id="money-value">${money(s.money)}</strong></div><div class="gem-value">${icon('gem')}<span id="gems-value">${number(s.gems)}</span></div></div></div>`;}
export function life(s){const g=goal(s),j=JOBS.find(j=>j.id===s.job);return `<div class="life-heading"><div><span class="eyebrow">${t('ui.income')}</span><div class="income"><strong id="income-value">${money(income(s))}</strong><span>/ ${t('ui.sec')}</span></div></div><span class="tag mint">${icon('bolt')}${t(j.name)}</span></div><div class="room room-${s.housing}">${scene(s)}<div class="room-label">${icon('life')}<span>${t(HOUSING[s.housing].name)}</span></div><span class="room-level">0${s.housing+1} / 03</span></div><button class="goal-card" ${action('goal',g.screen)}><span class="goal-icon">${icon('spark')}</span><span class="goal-copy"><span class="eyebrow">${t('ui.goal')}</span><strong class="goal-now">${goalText(g)}</strong><span class="goal-future">${t('ui.nextSoon')}: ${unlockText(s)}</span>${progress(g.progress,g.max)}</span>${icon('arrow')}</button><section class="collection-card"><div class="between"><span>${t('ui.accumulated')}</span><strong id="bank-value">${money(s.bank)}</strong></div>${button(`${icon('coin')}<span>${t('ui.collect')}</span>${icon('arrow')}`,'collect','','button primary collect-button',s.bank<1)}<small>${icon('clock')}${t('ui.bankCap')}</small><div class="next-unlock-strip">${s.housing<2?`<img src="./assets/room-${s.housing+1}.webp" width="56" height="38" alt="">`:icon('life')}<span>${t('ui.bigGoal')}: ${s.housing===2?t('ui.finishedGoal'):t('home.'+(s.housing+1))}</span></div></section><div class="life-shortcuts">${button(`${icon('list')}<span>${t('ui.tasks')}</span><b>${DAILY_QUESTS.filter(q=>s.daily[q.id]>=q.target&&!s.daily.claimed.includes(q.id)).length||'3'}</b>`,'tasks','','shortcut')}${button(`${icon('rating')}<span>${t('ui.achievements')}</span><b>${s.achievements.length}/${ACHIEVEMENTS.length}</b>`,'achievements','','shortcut')}</div>${s.level>=3?button(`${icon('gift')}${starterEligible(s)?t('ui.starter'):t('ui.bonuses')}`,'bonuses','','offers-link'):''}${s.boosts.length?`<span class="boost-pill">${icon('bolt')}<span id="boost-time"></span></span>`:''}${s.event!==null?button(`${icon('spark')}${t('ui.event')}${icon('arrow')}`,'event','','event-banner'):''}`;}
export function workScreen(s,view,branch){if(!s.tutorial)return `<div class="empty"><span class="big-icon">${icon('work')}</span><h2>${t('ui.work')}</h2><p>${t('ui.jobLocked')}</p>${button(t('ui.life'),'nav','life','button primary')}</div>`;return `<div class="page-title"><h1>${t('ui.work')}</h1><span class="muted">${s.jobs.length} / ${JOBS.length}</span></div><section class="side-job"><span class="section-icon">${icon('bolt')}</span><div><strong>${t('ui.sideJob')}</strong><small>${t('ui.sideDesc')}</small></div>${button(`+${money(income(s)*CONFIG.workSeconds)}<small>+${CONFIG.workXP} XP</small>`,'work','','button primary work-button',false)}</section><div class="segmented">${button(t('ui.career'),'workView','career',view==='career'?'selected':'')}${button(`${t('ui.skills')}${s.training?' ·':''}`,'workView','skills',view==='skills'?'selected':'')}</div>${view==='skills'?skillsScreen(s):`<div class="chips">${['all','service','tech','creative'].map(b=>button(t(b==='all'?'ui.all':'branch.'+b),'branch',b,branch===b?'chip active':'chip')).join('')}</div><div class="card-list">${JOBS.filter(j=>branch==='all'||branch===j.branch).map(j=>jobCard(s,j)).join('')}</div>`}`;}
function jobCard(s,j){const missing=jobRequirements(s,j),owned=s.jobs.includes(j.id),current=s.job===j.id;const requirements=missing.map(r=>r.kind==='level'?`${t('ui.level')} ${r.value}`:r.kind==='skill'?`${t('skill.'+r.id)} ${r.value}`:t((r.kind==='item'?'item.':'job.')+r.id));return `<article class="job-card ${current?'current-card':!owned&&missing.length?'locked-card':owned?'owned-card':'available-card'}"><div class="job-main"><span class="item-icon ${j.branch}">${icon(j.branch==='tech'?'computer':j.branch==='creative'?'spark':'work')}</span><div class="flex-grow"><h3>${t(j.name)}</h3><small>${t('branch.'+j.branch)} · ${t('ui.level')} ${j.levelRequirement}</small></div><strong class="rate">${money(j.incomePerSecond)}<small>/ ${t('ui.sec')}</small></strong></div>${!owned&&requirements.length?`<div class="requirements">${icon('lock')}${requirements.join(' · ')}</div>`:''}<div class="job-bottom"><span>${current?`<span class="current-label">${icon('check')}${t('ui.current')}</span>`:owned?t('ui.owned'):`${t('ui.hiring')} ${money(j.unlockCost)}`}</span>${button(current?t('ui.current'):owned?t('ui.choose'):t('ui.unlock'),'job',j.id,'button small '+(current?'quiet':'secondary'),current||(!owned&&missing.length>0)||(!owned&&s.money<j.unlockCost),!current&&(owned||!missing.length)?`data-price="${owned?0:j.unlockCost}"`:'')}</div></article>`;}
function skillsScreen(s){if(s.level<3)return `<div class="empty"><span class="big-icon">${icon('book')}</span><h2>${t('ui.skillsLocked')}</h2><p>${t('ui.shopHint')}</p></div>`;return `<p class="section-description">${t('ui.skillInfo')}</p><div class="card-list">${SKILLS.map((skill,i)=>{const busy=s.training?.skill===skill;return `<article class="skill-card"><span class="item-icon skill-${i}">${icon(['book','clock','spark','computer','sun'][i])}</span><div class="flex-grow"><h3>${t('skill.'+skill)} <b>${s.skills[skill]}</b></h3><small>${busy?`<span id="training-time"></span>`:`+1 · ${Math.ceil(trainingDuration(s))} ${t('ui.sec')}`}</small></div>${button(busy?t('ui.training'):`${t('ui.train')}<small>${money(trainingCost(s,skill))}</small>`,'train',skill,'button secondary small',!!s.training||s.money<trainingCost(s,skill)||s.skills[skill]>=100,!s.training&&s.skills[skill]<100?`data-price="${trainingCost(s,skill)}"`:'')}</article>`;}).join('')}</div>`;}
export function shopScreen(s,view,filter){return `<div class="page-title"><h1>${t('ui.shop')}</h1><span class="muted">${s.items.length} / ${ITEMS.length}</span></div><div class="segmented">${button(t('ui.items'),'shopView','items',view==='items'?'selected':'')}${button(t('ui.housing'),'shopView','housing',view==='housing'?'selected':'')}</div>${view==='housing'?housingScreen(s):s.level<2?`<div class="empty"><span class="big-icon">${icon('lock')}</span><h2>${t('ui.shopLocked')}</h2><p>${t('ui.shopHint')}</p>${button(t('ui.work'),'nav','work','button primary')}</div>`:`<div class="chips">${['all','owned'].map(k=>button(t('ui.'+k),'shopFilter',k,filter===k?'chip active':'chip')).join('')}</div><div class="shop-grid">${ITEMS.filter(i=>filter!=='owned'||s.items.includes(i.id)).map(i=>itemCard(s,i)).join('')}</div>`}`;}
function itemCard(s,i){const owned=s.items.includes(i.id),equipped=s.equipped[i.slot]===i.id,locked=s.level<i.levelRequirement;return `<article class="shop-card ${equipped?'current-card':owned?'owned-card':locked?'locked-card':'available-card'}"><button class="product-art ${i.rarity}" data-action="previewItem" data-id="${i.id}" aria-label="${t('ui.preview')}: ${t(i.name)}">${icon(['phone','computer','clothes','headphones','desk','chair','transport','camera','microphone'].includes(i.slot)?i.slot:i.slot==='monitor'?'computer':i.slot==='shoes'?'bolt':'spark')}<span>${owned?icon('check'):icon(locked?'lock':'spark')}</span></button><div class="product-info"><small class="rarity ${i.rarity}">${t('rarity.'+i.rarity)}</small><h3>${t(i.name)}</h3><p>+${Math.round(i.bonus*100)}% ${t('ui.incomeBonus')}</p>${button(equipped?`${icon('check')}${t('ui.equipped')}`:owned?t('ui.equip'):locked?`${icon('lock')}${t('ui.level')} ${i.levelRequirement}`:money(i.price),'item',i.id,'button product-button '+(equipped?'quiet':'secondary'),equipped||locked||(!owned&&s.money<i.price),!equipped&&!locked?`data-price="${owned?0:i.price}"`:'')}</div></article>`;}
function housingScreen(s){return `<p class="section-description">${t('ui.homeInfo')}</p><div class="card-list">${HOUSING.map(h=>`<article class="housing-card ${h.id===s.housing?'current-card':h.id<s.housing?'owned-card':s.level<h.levelRequirement?'locked-card':'available-card'}"><img src="./assets/room-${h.id}.webp" width="960" height="640" alt="${t(h.name)}" loading="lazy"><div class="housing-info"><div><h3>${t(h.name)}</h3><p>+${Math.round(h.bonus*100)}% ${t('ui.incomeBonus')} · ${t('ui.level')} ${h.levelRequirement}</p></div>${button(h.id===s.housing?t('ui.current'):h.id<s.housing?t('ui.owned'):`${t('ui.move')} · ${money(h.price)}`,'housing',h.id,'button '+(h.id===s.housing?'quiet':'secondary'),h.id!==s.housing+1||s.level<h.levelRequirement||s.money<h.price,h.id===s.housing+1&&s.level>=h.levelRequirement?`data-price="${h.price}"`:'')}</div></article>`).join('')}</div>`;}
export function rankingScreen(s,leaderboard,mode){return `<div class="page-title"><h1>${t('ui.rating')}</h1>${icon('rating')}</div><div class="league-hero"><span class="league-icon">${icon('rating')}</span><h2>${t('ui.localLeague')}</h2><p>${t('ui.npcNotice')}</p></div><div class="segmented">${button(t('ui.wealth'),'rankMode','wealth',mode==='wealth'?'selected':'')}${button(t('ui.level'),'rankMode','level',mode==='level'?'selected':'')}</div><ol class="rank-list">${leaderboard.list(s,mode).map((p,i)=>`<li class="rank-row ${p.id==='you'?'you':''}"><span class="rank-number">${String(i+1).padStart(2,'0')}</span><span class="npc-avatar npc-${i%4}">${p.id==='you'?'Z':p.name.slice(0,1)}</span><div class="flex-grow"><h3>${p.id==='you'?t('ui.you'):p.name}</h3><small>${t('ui.level')} ${p.level}</small></div><strong>${mode==='wealth'?money(p.wealth):p.level}</strong></li>`).join('')}</ol>`;}
export function tasks(s){return `<p class="section-description">${t('ui.dailyDesc')}</p><article class="gift-card">${icon('gift')}<div><h3>${t('ui.dailyGift')}</h3><small>${t('ui.dailyGiftDesc')}</small></div>${button(t(s.daily.gift?'ui.claimed':'ui.claim'),'gift','','button small secondary',s.daily.gift)}</article>${DAILY_QUESTS.map(q=>`<article class="quest-card"><h3>${t('quest.'+q.id)}</h3><div class="between"><small>${money(q.money)} · ${q.xp} XP · 1 ${icon('gem')}</small><span>${Math.min(s.daily[q.id],q.target)}/${q.target}</span></div>${progress(s.daily[q.id],q.target)}${button(t(s.daily.claimed.includes(q.id)?'ui.claimed':'ui.claim'),'quest',q.id,'button small secondary',s.daily.claimed.includes(q.id)||s.daily[q.id]<q.target)}</article>`).join('')}`;}
export function achievements(s){return ACHIEVEMENTS.map(a=>`<article class="achievement-card"><span class="item-icon ${s.achievements.includes(a.id)?'mint':''}">${icon(s.achievements.includes(a.id)?'check':'rating')}</span><div class="flex-grow"><h3>${t('achievement.'+a.id)}</h3><small>${compact(Math.min(statValue(s,a.stat),a.target))} / ${compact(a.target)} · ${a.gems} ${icon('gem')}</small>${progress(statValue(s,a.stat),a.target)}</div>${button(t(s.achievements.includes(a.id)?'ui.claimed':'ui.claim'),'achievement',a.id,'button small secondary',s.achievements.includes(a.id)||statValue(s,a.stat)<a.target)}</article>`).join('');}
export function settings(s){return `<label class="setting-row"><span>${t('ui.language')}</span><select id="language" aria-label="${t('ui.language')}">${[['ru','Русский'],['uk','Українська'],['en','English']].map(([l,n])=>`<option value="${l}" ${s.settings.language===l?'selected':''}>${n}</option>`).join('')}</select></label>${['sound','music','vibration','motion','effects'].map(k=>`<label class="setting-row"><span>${t('ui.'+k)}</span><input type="checkbox" data-setting="${k}" ${s.settings[k]?'checked':''}></label>`).join('')}<p class="section-description">${t('ui.notifications')}</p><div class="save-settings"><p>${t('ui.saveInfo')}</p>${button(t('ui.export'),'export','','button secondary')}${button(t('ui.import'),'import','','button secondary')}<input type="file" id="import-file" accept=".json,application/json" hidden>${button(t('ui.reset'),'reset','','button danger')}</div>`;}
